&quot;) 2.6.2 框架集成实现（LangGraph 条件边） LangGraph 的 conditional edges 是路由模式的正统表达：节点产出决策依据，条件函数返回下一个节点名。以下基于 langgraph 0.2.x 与 langchain-openai 0.2.x 编写（API 若有变动，以所用版本官方文档为准）。 &quot;&quot;&quot;第2章 路由：LangGraph 条件边实现。 结构：classify 节点 -&gt; 条件边按 (置信度, 意图) 分流到 cheap / strong / escalate 三个处理节点，各自连到 END。 依赖：pip install &quot;langgraph&gt;=0.2&quot; &quot;langchain-openai&gt;=0.2&quot; &quot;&quot;&quot; from __future__ import annotations import json import os from typing import Any, Literal, TypedDict from langchain_core.messages import HumanMessage, SystemMessage from langchain_openai import ChatOpenAI from langgraph.graph import END, START, StateGraph cheap_model = ChatOpenAI( model=os.environ.get(&quot;AGENT_LLM_MODEL&quot;, &quot;gpt-4o-mini&quot;), base_url=os.environ.get(&quot;AGENT_LLM_BASE_URL&quot;, &quot;https://api.openai.com/v1&quot;), api_key=os.environ[&quot;AGENT_LLM_API_KEY&quot;], temperature=0.0, ) strong_model = ChatOpenAI( model=os.environ.get(&quot;AGENT_LLM_MODEL_STRONG&quot;, &quot;gpt-4o&quot;), base_url=os.environ.get(&quot;AGENT_LLM_BASE_URL&quot;, &quot;https://api.openai.com/v1&quot;), api_key=os.environ[&quot;AGENT_LLM_API_KEY&quot;], temperature=0.2, ) CONFIDENCE_GATE = 0.8 ESCALATE_INTENTS = {&quot;complaint&quot;} class RouteState(TypedDict): &quot;&quot;&quot;流转状态：query 进，intent/confidence 路由依据，answer 出。&quot;&quot;&quot; query: str intent: str confidence: float answer: str handled_by: str def classify(state: RouteState) -&gt; dict[str, Any]: &quot;&quot;&quot;意图分类节点；解析失败 fail-open 为低置信度，交由强模型兜底。&quot;&quot;&quot; messages = [ SystemMessage( content='你是意图分类器，只输出 JSON：{&quot;intent&quot;: ' '&quot;billing&quot;|&quot;technical&quot;|&quot;complaint&quot;|&quot;other&quot;, &quot;confidence&quot;: 0到1}' ), HumanMessage(content=state[&quot;query&quot;]), ] try: data = json.loads(cheap_model.invoke(messages).content) intent = str(data.get(&quot;intent&quot;, &quot;other&quot;)) confidence = min(max(float(data.get(&quot;confidence&quot;, 0.0)), 0.0), 1.0) except (ValueError, TypeError, json.JSONDecodeError): intent, confidence = &quot;other&quot;, 0.0 return {&quot;intent&quot;: intent, &quot;confidence&quot;: confidence} def route_after_classify( state: RouteState, ) -&gt; Literal[&quot;cheap&quot;, &quot;strong&quot;, &quot;escalate&quot;]: &quot;&quot;&quot;条件边函数：只读状态，返回下一个节点名。&quot;&quot;&quot; if state[&quot;confidence&quot;] &lt; CONFIDENCE_GATE: return &quot;strong&quot; # 置信度兜底：宁升舱不冒险 if state[&quot;intent&quot;] in ESCALATE_INTENTS: return &quot;escalate&quot; if state[&quot;intent&quot;] in {&quot;billing&quot;, &quot;other&quot;}: return &quot;cheap&quot; return &quot;strong&quot; def cheap_answer(state: RouteState) -&gt; dict[str, str]: answer = cheap_model.invoke( [HumanMessage(content=f&quot;用户请求：{state['query']}
请直接简洁回答，100 字以内。&quot;)] ).content return {&quot;answer&quot;: answer, &quot;handled_by&quot;: &quot;cheap&quot;} def strong_answer(state: RouteState) -&gt; dict[str, str]: answer = strong_model.invoke( [HumanMessage(content=f&quot;用户请求：{state['query']}
请给出严谨、可执行的答复。&quot;)] ).content return {&quot;answer&quot;: answer, &quot;handled_by&quot;: &quot;strong&quot;} def escalate_answer(state: RouteState) -&gt; dict[str, str]: answer = strong_model.invoke( [ SystemMessage( content=&quot;你是投诉处理专员：先共情安抚，再给解决路径，&quot; &quot;不确定的补偿一律回复'转专员确认'。&quot; ), HumanMessage(content=f&quot;用户请求：{state['query']}&quot;), ] ).content return {&quot;answer&quot;: answer, &quot;handled_by&quot;: &quot;escalate&quot;} builder = StateGraph(RouteState) builder.add_node(&quot;classify&quot;, classify) builder.add_node(&quot;cheap&quot;, cheap_answer) builder.add_node(&quot;strong&quot;, strong_answer) builder.add_node(&quot;escalate&quot;, escalate_answer) builder.add_edge(START, &quot;classify&quot;) # 条件边：路由决策集中在这一个函数里，改路由只改这里 builder.add_conditional_edges( &quot;classify&quot;, route_after_classify, {&quot;cheap&quot;: &quot;cheap&quot;, &quot;strong&quot;: &quot;strong&quot;, &quot;escalate&quot;: &quot;escalate&quot;}, ) builder.add_edge(&quot;cheap&quot;, END) builder.add_edge(&quot;strong&quot;, END) builder.add_edge(&quot;escalate&quot;, END) graph = builder.compile() if __name__ == &quot;__main__&quot;: for q in [ &quot;我想重置登录密码&quot;, # 低置信度 -&gt; strong 兜底 &quot;这个月话费怎么多扣了 30 块？&quot;, # billing 高置信 -&gt; cheap &quot;你们这服务太差了，我要投诉！&quot;, # complaint -&gt; escalate ]: result: dict[str, Any] = graph.invoke({&quot;query&quot;: q}) print(f&quot;问：{q}
