&quot;.join(lines) def validate(self, name: str, args: dict[str, Any]) -&gt; str | None: &quot;&quot;&quot;执行前校验。返回 None 表示通过，否则返回可执行的错误说明。&quot;&quot;&quot; tool = self._tools.get(name) if tool is None: return f&quot;未知工具 {name}。合法工具：{list(self._tools)}。请从中选择或直接给出 final。&quot; missing = [k for k in tool.parameters.get(&quot;required&quot;, []) if k not in args] if missing: return f&quot;缺少必填参数 {missing}。参数定义：{json.dumps(tool.parameters, ensure_ascii=False)}&quot; for key, val in args.items(): spec = tool.parameters.get(&quot;properties&quot;, {}).get(key) if spec is None: return f&quot;参数 {key} 不在 schema 中。合法参数：{list(tool.parameters.get('properties', {}))}&quot; expect = spec.get(&quot;type&quot;) got = type(val).__name__ ok = { &quot;string&quot;: isinstance(val, str), &quot;number&quot;: isinstance(val, (int, float)) and not isinstance(val, bool), &quot;integer&quot;: isinstance(val, int) and not isinstance(val, bool), &quot;boolean&quot;: isinstance(val, bool), }.get(expect, True) if not ok: return f&quot;参数 {key} 应为 {expect}，实际为 {got}（值：{val!r}）。&quot; if &quot;enum&quot; in spec and val not in spec[&quot;enum&quot;]: return f&quot;参数 {key}={val!r} 不在合法枚举 {spec['enum']} 中。&quot; return None def call(self, name: str, args: dict[str, Any]) -&gt; str: &quot;&quot;&quot;执行工具。任何失败都返回可读错误文本——错误也是观察。&quot;&quot;&quot; err = self.validate(name, args) if err: return f&quot;[调用被拒绝] {err}&quot; try: return self._tools[name].handler(args) except Exception as exc: # noqa: BLE001 —— 执行层兜底，异常转观察 return f&quot;[工具执行异常] {type(exc).__name__}: {exc}&quot; # ---------- 演示工具：一个要算的、一个要查的 ---------- _BIN_OPS = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul, ast.Div: op.truediv} def safe_calc(expr: str) -&gt; str: &quot;&quot;&quot;四则运算安全求值：用 ast 白名单，杜绝 eval 任意代码执行。&quot;&quot;&quot; def _eval(node: ast.AST) -&gt; float: if isinstance(node, ast.Expression): return _eval(node.body) if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)): return float(node.value) if isinstance(node, ast.BinOp) and type(node.op) in _BIN_OPS: return _BIN_OPS[type(node.op)](_eval(node.left), _eval(node.right)) if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub): return -_eval(node.operand) raise ValueError(f&quot;表达式包含不允许的元素：{ast.dump(node)[:60]}&quot;) try: return str(_eval(ast.parse(expr, mode=&quot;eval&quot;))) except SyntaxError as exc: raise ValueError(f&quot;表达式语法错误：{expr!r}（{exc.msg}）&quot;) from exc EMPLOYEES = { &quot;王伟&quot;: {&quot;dept&quot;: &quot;工程部&quot;, &quot;reimburse&quot;: 3280.0}, &quot;李娜&quot;: {&quot;dept&quot;: &quot;市场部&quot;, &quot;reimburse&quot;: 1560.5}, } def lookup_employee(name: str) -&gt; str: if name not in EMPLOYEES: raise KeyError(f&quot;查无此人：{name}。在册员工：{list(EMPLOYEES)}&quot;) info = EMPLOYEES[name] return json.dumps(info, ensure_ascii=False) def build_registry() -&gt; ToolRegistry: reg = ToolRegistry() reg.register(Tool( name=&quot;calculator&quot;, description=&quot;对四则运算表达式求值并返回数字。表达式只允许数字与 + - * / ( )。&quot;, parameters={ &quot;type&quot;: &quot;object&quot;, &quot;properties&quot;: {&quot;expression&quot;: {&quot;type&quot;: &quot;string&quot;, &quot;description&quot;: &quot;如 (1240+360)/4&quot;}}, &quot;required&quot;: [&quot;expression&quot;], }, handler=lambda a: safe_calc(a[&quot;expression&quot;]), )) reg.register(Tool( name=&quot;lookup_employee&quot;, description=&quot;按姓名查询员工的部门与待报销金额。不要用它查不在册人员。&quot;, parameters={ &quot;type&quot;: &quot;object&quot;, &quot;properties&quot;: { &quot;name&quot;: {&quot;type&quot;: &quot;string&quot;, &quot;description&quot;: &quot;员工全名，如 王伟&quot;, &quot;enum&quot;: list(EMPLOYEES)}, # 枚举约束：拦掉编造的姓名 }, &quot;required&quot;: [&quot;name&quot;], }, handler=lambda a: lookup_employee(a[&quot;name&quot;]), )) return reg # ---------- agent 循环 ---------- SYSTEM_PROMPT = &quot;&quot;&quot;你是能调用工具的助手。可用工具： {tools} 每轮只输出一个 JSON 对象，二选一： 1) {{&quot;thought&quot;: &quot;简短理由&quot;, &quot;tool&quot;: &quot;工具名&quot;, &quot;arguments&quot;: {{...}}}} 2) {{&quot;thought&quot;: &quot;简短理由&quot;, &quot;final&quot;: &quot;最终答案&quot;}} 规则：参数值只能来自任务文本或工具返回结果，禁止编造；工具报错后应根据错误信息修正再试。&quot;&quot;&quot; def run_agent(task: str, registry: ToolRegistry, max_steps: int = 10, token_budget: int = 30000) -&gt; str: &quot;&quot;&quot;agent 主循环。停止条件：final 声明 / 最大步数 / 重复调用检测。&quot;&quot;&quot; history: list[str] = [f&quot;【任务】{task}&quot;] last_call: tuple[str, str] | None = None for step in range(1, max_steps + 1): prompt = &quot;
&quot;.join(history) + &quot;

请输出下一个 JSON。&quot; raw = llm(prompt, system=SYSTEM_PROMPT.format(tools=registry.describe_for_model()), temperature=0.1) try: text = raw.strip() if text.startswith(chr(96) * 3): # 围栏用 chr 构造，防裸反引号截断文档 text = text.strip(chr(96)).lstrip(&quot;json&quot;) decision = json.loads(text) except json.JSONDecodeError: history.append(f&quot;【观察】输出解析失败：{raw[:200]}。请严格按 JSON 格式重发。&quot;) continue # 错误路径：解析失败转观察，消耗一轮 if &quot;final&quot; in decision: return str(decision[&quot;final&quot;]) name, args = str(decision.get(&quot;tool&quot;)), decision.get(&quot;arguments&quot;, {}) if not isinstance(args, dict): history.append(f&quot;【观察】arguments 必须是对象，收到 {type(args).__name__}。&quot;) continue # 死循环检测：相同 (tool, args) 连续出现，注入提醒，再犯即终止 key = (name, json.dumps(args, ensure_ascii=False, sort_keys=True)) if key == last_call: history.append(&quot;【观察】你已用相同参数调用过该工具，请改变策略或给出 final。&quot;) last_call = None continue last_call = key observation = registry.call(name, args) if len(observation) &gt; 800: # 观察截断：保护上下文预算 observation = observation[:800] + f&quot;…（截断，原长 {len(observation)} 字符）&quot; history.append(f&quot;【调用】{name}({json.dumps(args, ensure_ascii=False)})&quot;) history.append(f&quot;【观察】{observation}&quot;) print(f&quot;[step {step}] {name} -&gt; {observation[:80]}&quot;) return f&quot;已达最大步数 {max_steps}，任务未完成。已获信息：
