&quot; &quot;如果你无法完成该子任务，输出必须以 [UNRESOLVED]: 开头并说明原因；&quot; &quot;否则直接给出该子任务的成果。&quot; ) step.attempts += 1 if &quot;[UNRESOLVED]&quot; in reply[:30]: step.result = reply.strip() print(f&quot; 执行失败(第{step.attempts}次)：{reply[:60]}&quot;) else: step.status, step.result = &quot;done&quot;, reply.strip() print(f&quot; 完成：{step.description[:40]} -&gt; {step.result[:50]}&quot;) # ---------- 重规划 ---------- def replan(state: PlanState) -&gt; None: &quot;&quot;&quot;局部重规划：携带已完成结果与失败原因，只重排未完成部分。 修订纪律：默认只替换未完成项，已完成项的结果作为上下文保留—— 白板重规划等于抹掉状态、重复烧钱。 &quot;&quot;&quot; failed = [s for s in state.steps if s.status == &quot;failed&quot;] failure_note = &quot;
&quot;.join( f&quot;-「{s.description}」失败原因：{s.result}&quot; for s in failed ) done_part = &quot;
&quot;.join( f&quot;- {s.description} -&gt; {s.result}&quot; for s in state.steps if s.status == &quot;done&quot; ) context = ( f&quot;以下子任务已完成，新计划必须复用其结果、不得重复：
{done_part}
&quot; f&quot;以下子任务多次失败，新计划应换路线、拆细或绕过：
{failure_note}&quot; ) state.steps = [ s for s in state.steps if s.status == &quot;done&quot; ] + make_plan(state.goal, context=context) print(f&quot;[重规划 #{state.replans}] 新计划：&quot;) for i, s in enumerate([x for x in state.steps if x.status == &quot;pending&quot;], 1): print(f&quot; {i}. {s.description[:50]}&quot;) # ---------- 状态机主循环 ---------- def run(goal: str, max_attempts: int = 2, max_replans: int = 2) -&gt; PlanState: &quot;&quot;&quot;plan -&gt; execute -&gt; replan 主状态机。 触发条件：同一计划项连续失败 max_attempts 次 -&gt; 局部重规划； 终止条件：全部完成（成功）/ 重规划次数耗尽（如实报失败）。 &quot;&quot;&quot; state = PlanState(goal=goal) state.steps = make_plan(goal) print(&quot;[初始计划]&quot;) for i, s in enumerate(state.steps, 1): print(f&quot; {i}. {s.description[:50]}&quot;) while state.outcome == &quot;running&quot;: pending = [s for s in state.steps if s.status == &quot;pending&quot;] if not pending: state.outcome = &quot;success&quot; break step = pending[0] print(f&quot;[执行] {step.description[:50]}&quot;) execute_step(step, state) if step.status != &quot;done&quot;: if step.attempts &gt;= max_attempts: step.status = &quot;failed&quot; state.replans += 1 if state.replans &gt; max_replans: state.outcome = &quot;failed&quot; # 硬闸：重规划耗尽，如实报告 break replan(state) if all(s.status == &quot;done&quot; for s in state.steps): state.outcome = &quot;success&quot; return state if __name__ == &quot;__main__&quot;: result = run(goal=( &quot;为'团队周报自动化'写一份实施方案：包括数据从哪来、汇总什么指标、&quot; &quot;如何自动分发给五个部门。要求分点、可直接执行。&quot; )) print(&quot;
=== 结果 ===&quot;) print(&quot;结局：&quot;, result.outcome, &quot;| 重规划次数：&quot;, result.replans) for s in result.steps: print(f&quot;[{s.status}] {s.description[:40]}&quot;) 6.6.2 框架集成实现（CrewAI，hierarchical process） CrewAI 的 hierarchical 模式是"计划—分派—验收"分离的最短实现：管理者（manager）由 LLM 充当规划器，决定把任务派给谁、何时算完成；执行者只对分派的子任务负责。以下基于 crewai 0.x（2024–2025 系列）公开 API 编写；CrewAI 版本迭代较快，若参数名有出入请以所装版本官方文档为准。API Key 通过环境变量读取（CrewAI 默认读取 OPENAI_API_KEY 及相关模型配置）。 &quot;&quot;&quot;规划模式的 CrewAI 实现：hierarchical process，由 manager 分解与分派任务。 依赖：pip install crewai 说明：hierarchical 模式下 manager_llm 充当&quot;规划器&quot;，负责分解、分派与验收； agents 是执行器，只对分派的子任务负责。 &quot;&quot;&quot; import os from crewai import Agent, Crew, Process, Task MODEL = os.environ.get(&quot;AGENT_LLM_MODEL&quot;, &quot;gpt-4o-mini&quot;) researcher = Agent( role=&quot;资深行业研究员&quot;, goal=&quot;高效收集并核实与任务相关的关键事实&quot;, backstory=&quot;十年行业研究经验，只报告可核实的内容，不臆测数据。&quot;, allow_delegation=False, verbose=False, ) writer = Agent( role=&quot;首席分析撰稿人&quot;, goal=&quot;把研究结论整合为结构清晰、有明确建议的短报告&quot;, backstory=&quot;技术分析师出身，用词克制，每个结论都注明依据。&quot;, allow_delegation=False, verbose=False, ) research_task = Task( description=( &quot;为报告《{topic}》收集三类信息：市场规模与增速、主要玩家、&quot; &quot;最近一年的两个关键变化。只列经核实的事实。&quot; ), expected_output=&quot;5-8 条要点，每条一句话，并注明信息性质（公开报道/行业共识）。&quot;, agent=researcher, ) report_task = Task( description=( &quot;基于研究要点撰写一页纸决策简报。结构固定：结论先行、三条依据、&quot; &quot;一条风险提示。若研究要点不足以支撑结论，如实说明缺口而不是编造。&quot; ), expected_output=&quot;300 字以内的中文简报。&quot;, agent=writer, ) crew = Crew( agents=[researcher, writer], tasks=[research_task, report_task], process=Process.hierarchical, # 管理者模式：计划-分派-验收分离 manager_llm=MODEL, # manager 即规划器：决定谁做什么、何时算完成 verbose=True, ) if __name__ == &quot;__main__&quot;: result = crew.kickoff(inputs={&quot;topic&quot;: &quot;端侧 AI 芯片市场&quot;}) print(&quot;最终交付：
&quot;, result.raw) 6.6.3 生产化改造清单 错误处理：计划 JSON 解析失败带错误重试一次，再失败降级为单步执行并标注"无计划模式"；执行异常计为该项失败而非中断任务。 超时：计划生成设独立超时（计划是关键路径）；每个计划项执行设超时并计入失败重试。 并发：依赖关系解析后，无依赖计划项并发执行；写操作项保持串行与业务顺序。 缓存：计划按（目标、上下文哈希）缓存；已完成计划项结果持久化，重跑任务从断点续做而非从头再来。 可观测：记录计划版本、每项状态流转、重规划触发原因；"重规划次数高"与"单项反复失败"是首要告警。 成本控制：计划用强模型、执行按项难度选模型；设任务级步数与 token 预算，预算过半进度不足时主动触发重评估。 计划验证：结构验证代码化（非空、条目上限、依赖无环）；引用的工具/资源与注册表对账；执行前一次模型可行性评审。 重规划治理：修订必须携带已完成状态与失败原因；全盘重规划设更高门槛与审批；版本留痕可审计。 人工介入点：计划执行前展示给用户确认（对齐性价比最高的一步）；写操作项与高风险项设审批闸。 评测：建任务分解评测集（可执行性、粒度、依赖正确性、完成率），换模型或改提示后回归。 6.7 概览 / 核心要点 / 结论 6.7.1 本章小结 规划模式把长程任务从"赌模型隐式状态的稳定性"改写为"管理一份显式的工作分解结构"：计划生成、状态跟踪、重规划触发、计划验证四个部件各司其职。计划—执行的分离程度是一条光谱——从 ReAct 的纯交织，到一次性分离（HuggingGPT、Plan-and-Solve）、占位符分离（ReWOO），再到按需递归（ADaPT）——选择依据是环境的稳定性与执行器的能力，工程上最常见的答案是"计划管方向、ReAct 管脚下"。四十年经典规划留下的形式纪律（STRIPS 的状态形式化、HTN 的分解方法库、BDI 的意图坚持性）在 LLM 时代不是古董，而是治住计划幻觉、过度坚持与计划抖动的药方。 6.7.2 核心要点 显式计划的三重收益：跨步骤全局一致、进度可观测可定位、失败可局部重试而非从头再来。 计划—执行分离是光谱不是二选一：环境稳定用分离式，环境多变用交织或按需递归，生产常见形态是顶层分离、底层交织。 计划粒度的判据：每条计划项是执行器一次可验证的能力单元；粒度随执行器能力浮动（ADaPT 的核心洞察）。 ReWOO 的占位符解决了分离式的深层矛盾：计划可以引用尚未产生的执行结果，一次生成、不必预知。 重规划四触发器：子任务反复失败、假设被证伪、环境变化、预算越界；修订纪律是带证据、局部优先、版本留痕；意图坚持性（BDI 遗产）要求局部失败默认局部修订，全盘推翻需过门槛。 计划验证四层：结构验证（代码化）、可行性评审、执行中对判据、防计划—执行漂移。 三种失效要有对策：计划幻觉靠结构验证，过度坚持靠硬性触发器，计划抖动靠修订门槛。 单步任务、强探索任务、环境快变任务不要规划；"是否需要计划"本身就是路由的第一步。 6.7.3 结论 规划的价值不在"有一份计划"这个形式，而在它把长程任务的失败模式从不可诊断的"整体跑偏"变成可管理的"第 N 项需要处理"。LLM 让生成一份像样的计划变得便宜，但计划的好坏——粒度是否匹配执行器、依赖是否真实、假设是否站得住——仍然取决于工程纪律。实践者的功课是记住两个决策、一条纪律：分离与交织怎么选看环境，粒度粗细怎么看执行器，重规划必须带着证据与门槛。做到这三点，规划就从一篇"看起来周密的文字"变成智能体系统里最硬的那根骨架。 6.8 延伸阅读与参考链接 论文 HuggingGPT: Solving AI Tasks with ChatGPT and its Friends in Hugging Face（Shen et al., 2023）：arXiv:2303.17580 Plan-and-Solve Prompting: Improving Zero-Shot Chain-of-Thought Reasoning by Large Language Models（Wang et al., 2023）：arXiv:2305.04091 Tree of Thoughts: Deliberate Problem Solving with Large Language Models（Yao et al., 2023）：arXiv:2305.10601 ReWOO: Decoupling Reasoning from Observations for Efficient Augmented Language Models（Xu et al., 2023）：arXiv:2305.18323 ADaPT: As-Need