l, # 流水线；hierarchical 会引入管理者角色自动分层委派 verbose=True, ) if __name__ == &quot;__main__&quot;: try: result = crew.kickoff(inputs={&quot;topic&quot;: &quot;API 网关限流&quot;}) except Exception as exc: raise SystemExit(f&quot;crew 运行失败：{exc}&quot;) # 失败显式退出，不带病输出 print(&quot;
