改写提示词以修复失败，保持简短。只输出新提示词本身。&quot;, system=&quot;你是提示词工程专家。&quot;, temperature=0.7, ) return out.strip() or prompt except Exception: return prompt def evolve(seed: str, library: SkillLibrary) -&gt; Skill | None: &quot;&quot;&quot;主循环：逐代评估种群，满分即停；否则选最优变异出下一代。&quot;&quot;&quot; population = [seed] best: Skill | None = None for gen in range(MAX_GEN): scored: list[tuple[str, float, list[str]]] = [] for p in population: s, fails = evaluate(p) skill = Skill(f&quot;amount-extract-g{gen}&quot;, p, s, &quot;; &quot;.join(fails[:2])) library.add(skill) if best is None or s &gt; best.score: best = skill scored.append((p, s, fails)) print(f&quot;[gen {gen}] score={s:.2f} fails={len(fails)}&quot;) if best and best.score &gt;= 0.999: # 满分提前停止，省预算 break scored.sort(key=lambda x: -x[1]) top_prompt, _, top_fails = scored[0] # 选择：截断式选最优 population = [mutate(top_prompt, top_fails) for _ in range(POP_SIZE)] return best if __name__ == &quot;__main__&quot;: lib = SkillLibrary() seed_prompt = &quot;从输入文本中提取订单金额，输出一个整数（单位元），不要输出其他内容。&quot; winner = evolve(seed_prompt, lib) if winner is None: raise SystemExit(&quot;进化未产出任何可用技能&quot;) # 诚实失败，不硬凑结果 print(&quot;
最优技能得分：&quot;, winner.score) print(&quot;提示词：&quot;, winner.prompt) print(&quot;失败记录：&quot;, winner.note or &quot;无&quot;) print(&quot;技能库规模：&quot;, len(lib.skills)) 9.6.2 框架集成实现（DSPy：提示词是编译产物） DSPy 把手写提示的"手工雕琢"替换为声明式模块加自动编译：模块定义输入输出签名（Signature），优化器（如 BootstrapFewShot）用少量标注样例自动生成少样本演示并注入。以下按 dspy 2.5+/3.x API 编写，字段名随版本演进请以官方文档为准。 &quot;&quot;&quot;第 9 章 框架集成实现：DSPy 版提示程序优化。 安装：pip install &quot;dspy&gt;=2.5&quot; 运行前：export AGENT_LLM_API_KEY=... 等（与本章其余示例一致）。 注：按 dspy 2.5+/3.x API 编写，以官方文档为准。 &quot;&quot;&quot; import os import dspy lm = dspy.LM( model=f&quot;openai/{os.environ.get('AGENT_LLM_MODEL', 'gpt-4o-mini')}&quot;, api_key=os.environ[&quot;AGENT_LLM_API_KEY&quot;], api_base=os.environ.get(&quot;AGENT_LLM_BASE_URL&quot;, &quot;https://api.openai.com/v1&quot;), max_tokens=512, ) dspy.configure(lm=lm) class ExtractAmount(dspy.Signature): &quot;&quot;&quot;从文本中提取订单金额，输出整数（单位元）。&quot;&quot;&quot; text: str = dspy.InputField(desc=&quot;包含金额的原始文本&quot;) amount: int = dspy.OutputField(desc=&quot;金额整数，单位元&quot;) class AmountExtractor(dspy.Module): &quot;&quot;&quot;声明式模块：不手写提示，交给优化器编译。&quot;&quot;&quot; def __init__(self) -&gt; None: super().__init__() self.extract = dspy.ChainOfThought(ExtractAmount) def forward(self, text: str): return self.extract(text=text) TRAIN: list[tuple[str, int]] = [ (&quot;订单总额 428 元，已支付&quot;, 428), (&quot;实付199元&quot;, 199), (&quot;金额：¥3,200（含税）&quot;, 3200), (&quot;退款 15 元后的余额是 985 元&quot;, 985), ] def metric(example, pred, trace=None) -&gt; bool: &quot;&quot;&quot;度量函数：优化器用它判卷；解析失败一律算错。&quot;&quot;&quot; try: return int(pred.amount) == example.amount except Exception: return False def build_trainset() -&gt; list[dspy.Example]: out = [dspy.Example(text=t, amount=a).with_inputs(&quot;text&quot;) for t, a in TRAIN] if not out: raise ValueError(&quot;训练集为空，无法编译&quot;) return out if __name__ == &quot;__main__&quot;: trainset = build_trainset() program = AmountExtractor() # 先跑未编译基线（失败不阻断，继续编译） try: base = program(text=trainset[0].text) print(&quot;基线输出：&quot;, base.amount) except Exception as exc: print(&quot;基线调用失败（继续编译流程）：&quot;, exc) optimizer = dspy.BootstrapFewShot( metric=metric, max_bootstrapped_demos=2, max_labeled_demos=2 ) optimized = optimizer.compile(program, trainset=trainset) for text, gold in [(&quot;本月消费合计 12,088元&quot;, 12088), (&quot;运费 8 元已含&quot;, 8)]: try: pred = optimized(text=text) print(f&quot;{text} -&gt; {pred.amount}（期望 {gold}）&quot;) except Exception as exc: print(f&quot;{text} -&gt; 调用失败：{exc}&quot;) # 进阶：dspy.MIPROv2(metric=metric, auto=&quot;light&quot;) 可同时优化指令与少样本示例 9.6.3 生产化改造清单 错误处理：评估调用失败按错误计分而非重试到通过；进化无产出时显式退出并保留最优种子。 预算控制：代数、种群、总调用数、总费用四重预算硬编码；满分即停。 评估器治理：评估集与选择集分离；高分个体定期人工抽查，防 Goodhart。 并发评估：种群内并行调用（线程池/asyncio），评估阶段是循环的延迟大头。 缓存：相同提示词+样例的评估结果缓存；进化重跑不重复计费。 可观测：每代记录最优/平均得分、失败样例、变异来源，进化轨迹可回放可审计。 技能库治理：容量上限、去重合并、复用失败自动降权、定期用新评测集回测全库。 成本控制：廉价评估器前置快筛；变异用小模型、终选用强模型的双档组合。 9.7 概览 / 核心要点 / 结论 本章小结 智能体的学习不必然发生在权重里。非参数化路线把经验固化为提示、技能、经验与程序四类文本工件，用"捕获—工件化—复用—修正"的闭环换取即时生效、可审计、低成本的持续改进；进化循环在此之上加入主动搜索，用生成-评估-选择-变异把改进自动化。从 Holland 的进化计算骨架，到 Reflexion 的语言化反馈、Voyager 的技能库、DSPy 的提示编译，再到 AlphaEvolve 在数学开放问题与 Google 生产系统上的双重兑现，这条路线已经完成了从原型到生产的关键一跃。它的一切收益都以一个前提为抵押：存在廉价、自动、可信的评估器——守护这个前提，是学习型智能体系统的第一职责。 核心要点 非参数化学习改工件不改权重：即时生效、可读可审计、可回滚，是智能体迭代的首选路线。 经验必须工件化：情境、行动、结果、教训、置信度、来源，六要素缺一不可。 进化循环的命门是评估器：廉价、自动、可信三条件缺一，循环就在优化噪声。 变异要用有语义的 LLM 改写（diff 式），保留已验证部分；双模型 ensemble 平衡广度与深度。 选择要兼顾质量与多样性（MAP-Elites 思想），防止种群过早收敛到单一套路。 技能"验证通过才入库"，经验按置信度分级，低置信经验只参考不主导。 警惕 Goodhart 陷阱与回音室：评估集分离、人工抽查、外部信号定期校准。 预算硬编码：代数、调用数、费用三重上限；没有预算的进化循环是烧钱机。 结论 学习与适应把智能体从"一次性交付的工具"变成"越用越好的系统"。这件事在工程上已经不需要信仰：Voyager 证明了技能可以积累，DSPy 证明了提示可以编译，AlphaCodium 证明了流程可以自我修正，AlphaEvolve 证明了进化循环能刷新五十六年的算法纪录并优化支撑自身的生产系统。工程师要做的判断始终朴素：这个任务有没有可信的评估信号？经验值不值得沉淀？循环的预算和防腐机制配齐了没有？三问过关，就让系统开始积累复利；不过关，就诚实地把资源投在单次执行的质量上——知道何时不学，同样是这门手艺的一部分。 9.8 延伸阅读与参考链接 论文 arXiv:2303.11366 Reflexion：语言化反思的情景式在线学习（NeurIPS 2023，详见第 4 章）。 arXiv:2305.16291 Voyager：开放世界中的技能库终身学习智能体。 arXiv:2310.03714 DSPy：把提示词作为编译产物程序化优化（ICLR 2024）。 arXiv:2401.08500 AlphaCodium：测试驱动的迭代编码