mpts=4, ) # 模拟执行者：第1轮故意漂移（写成速度广告），第2轮吸收反馈回到正轨。 scripted = [&quot;极速云盘，下载提速300%，注册即送百G空间！&quot;, &quot;数据备份，稳健之选：云端守护，安全可靠每一天。&quot;] cursor = {&quot;i&quot;: 0} def agent_step(feedback: str | None) -&gt; str: # 真实场景：把 feedback 回注给模型重新产出；演示用确定性脚本按序取产出。 i = min(cursor[&quot;i&quot;], len(scripted) - 1) cursor[&quot;i&quot;] += 1 return scripted[i] monitor = GoalMonitor(goal) status, history = monitor.run(agent_step) print(f&quot;最终状态: {status}，共 {len(history)} 轮。&quot;) 11.6.2 框架集成实现（LangGraph：工作节点 + 监控节点的条件回路） 在 LangGraph（1.2.12 实测）里，目标监控最自然的形态是"工作节点 → 监控节点 → 条件边"：监控节点判定后由条件边决定回到工作节点（带反馈）、结束（成功）还是终止（超预算）。依赖：pip install langgraph openai。 &quot;&quot;&quot;LangGraph 目标监控回路：draft（工作）-&gt; monitor（判据+裁判）-&gt; 条件路由。 依赖：pip install langgraph openai # langgraph==1.2.12 实测 运行前设置 AGENT_LLM_API_KEY（可选 BASE_URL / MODEL），未设置将直接报错。 &quot;&quot;&quot; from __future__ import annotations import os import re from typing import Literal, TypedDict from langgraph.graph import START, StateGraph def llm(prompt: str, system: str = &quot;&quot;, temperature: float = 0.3) -&gt; str: &quot;&quot;&quot;统一的模型接入辅助函数（OpenAI 兼容协议，只读环境变量）。&quot;&quot;&quot; from openai import OpenAI client = OpenAI( base_url=os.environ.get(&quot;AGENT_LLM_BASE_URL&quot;, &quot;https://api.openai.com/v1&quot;), api_key=os.environ[&quot;AGENT_LLM_API_KEY&quot;], ) model = os.environ.get(&quot;AGENT_LLM_MODEL&quot;, &quot;gpt-4o-mini&quot;) messages = ([{&quot;role&quot;: &quot;system&quot;, &quot;content&quot;: system}] if system else []) + [ {&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: prompt} ] resp = client.chat.completions.create(model=model, messages=messages, temperature=temperature) return resp.choices[0].message.content or &quot;&quot; class MonitorState(TypedDict): goal: str # 原始目标文本（漂移比对基准） feedback: str # 监控反馈，回注给工作节点 attempts: int # 预算计数 artifact: str # 当前产出 status: str # running / success / budget_exhausted MAX_ATTEMPTS = 4 BANNED = re.compile(r&quot;最(好|强)|第一&quot;) # 约束：禁止绝对化用语 def draft(state: MonitorState) -&gt; MonitorState: &quot;&quot;&quot;工作节点：根据目标（和监控反馈）产出。&quot;&quot;&quot; prompt = f&quot;目标：{state['goal']}
