judge(answer) self.eval_results.append({&quot;span&quot;: span.name, &quot;score&quot;: score}) span.attributes[&quot;gen_ai.evaluation.score&quot;] = score def _export(self) -&gt; None: # 生产替换点：换成 opentelemetry.sdk.trace.export 或 langfuse.sdk 上报。 # 此处本地打印，保持零依赖可运行。 def render(s: Span, depth: int) -&gt; None: gen = {k: v for k, v in s.attributes.items() if k.startswith(&quot;gen_ai.&quot;)} print(&quot; &quot; * depth + f&quot;{s.name} [{s.duration_ms():.1f}ms] {gen}&quot;) for c in s.children: render(c, depth + 1) for r in self.roots: render(r, 0) # ---------------- 模拟业务链路：检索 -&gt; 生成 -&gt; 巡检 ---------------- def fake_retrieve(query: str) -&gt; list[str]: time.sleep(0.01) return [f&quot;doc#{hash(query) % 90 + 10}：季度营收 1200 万元，同比增长 18%&quot;] def fake_generate(context: list[str]) -&gt; str: time.sleep(0.02) return f&quot;根据 {context[0].split('：')[0]}，本季度营收同比增长 18%。&quot; def simple_judge(answer: str) -&gt; int: &quot;&quot;&quot;玩具裁判：含具体数字给 4 分，含模糊词扣分。生产中换 LLM 裁判。&quot;&quot;&quot; base = 4 if &quot;18%&quot; in answer else 2 return max(1, base - (1 if any(w in answer for w in (&quot;大概&quot;, &quot;可能&quot;)) else 0)) if __name__ == &quot;__main__&quot;: random.seed(42) tracer = GenAITracer(sample_eval_rate=1.0) # 演示用全采样，生产建议 0.01-0.05 for i, query in enumerate([&quot;本季度营收如何&quot;, &quot;同比增长多少&quot;, &quot;云支出情况&quot;]): with tracer.span(&quot;agent.run&quot;, **{ &quot;gen_ai.system&quot;: &quot;demo-agent&quot;, &quot;gen_ai.request.model&quot;: &quot;gpt-4o-mini&quot;, &quot;session.id&quot;: f&quot;s-{i}&quot;, }) as run: with tracer.span(&quot;retrieval.search&quot;, query=query) as r: docs = fake_retrieve(query) r.attributes[&quot;doc.count&quot;] = len(docs) with tracer.span(&quot;llm.chat&quot;, **{ &quot;gen_ai.prompt&quot;: query, &quot;gen_ai.usage.input_tokens&quot;: 120, &quot;gen_ai.usage.output_tokens&quot;: 30, }) as call: answer = fake_generate(docs) call.attributes[&quot;gen_ai.completion&quot;] = answer[:50] tracer.maybe_eval(run, answer, simple_judge) tracer._export() scores = [e[&quot;score&quot;] for e in tracer.eval_results] if scores: print(f&quot;
[metric] 抽样 eval 均分={sum(scores) / len(scores):.2f}（n={len(scores)}）&quot;) print(f&quot;[metric] eval 结果将随 trace 一并汇入监控后端：{os.getenv('OTEL_EXPORTER', 'stdout')}&quot;) 19.6.3 生产化改造清单 错误处理：裁判输出解析失败必须降级（启发式或跳过）并计数，禁止让评估流水线因裁判抖动而整体失败；裁判失效率进监控。 超时与并发：黄金集回归用有界并发跑（如 8 路），单案例设超时；超时计入失败而非崩溃。 缓存：以"案例 ID + 被测版本 + 裁判版本"为键缓存裁判结论，重复回归不重复付费；被测版本变更才失效。 可观测：评估体系自身也要可观测——裁判调用数、成本、失效率、黄金集各层耗时做成看板，评估流水线挂了要有告警。 成本控制：抽样分层（塔基全量、裁判抽样）；成对比较换序只在关键维度启用；长文本先截断或分段再评。 数据卫生：黄金集进版本管理并设访问控制；金丝雀串检测泄漏；对执行 agent 保密参考答案；坏案例回流走人工标注闸门。 裁判治理：裁判与执行模型异源；定期人工标定一致率；rubric 变更走评审；对照样本常驻评估集做裁判体检。 门禁纪律：阈值绑定基线相对比较；例外合并强制留痕并告警；分数必须绑定"代码×数据集×裁判"三元组版本。 在线联动：metric 异常（成功率、p95、eval 均分）接告警与自动回滚；降级事件（第 12 章）打标进 trace，降级率超阈值同样告警。 19.7 概览 / 核心要点 / 结论 本章小结 评估与监控把智能体系统的质量从"感觉"变成"工程事实"：评估金字塔用三经济学分层（断言高频免费、回归发布前把关、A/B 终审真相），LLM-as-judge 补上语义判据但必须消位置偏差、控冗长偏差并定期人工标定，黄金集按分层、版本化、防污染、保鲜四原则管理，CI 门禁把分数变成发布流程的一等公民，在线 trace/metric/eval 三件套以分位值与切片盯住真实流量。评估不是开发完成后的附加题，而是与提示词、代码同等地位的系统构件——它决定了一个团队能不能安全地快速迭代。 核心要点 评估金字塔三层是三种经济学：塔基每次改动跑，塔身每次发布跑，塔尖低频高置信；缺任何一层都会让某类失败直通生产。 LLM-as-judge 适用前提是裁判显著强于选手；成对比较换序取平均消位置偏差，rubric 显式列"简洁性"消冗长偏差，裁判与执行模型异源消自我偏好。 绝对分数会漂移，成对相对判断不会；必须用绝对分时给锚定样例。 黄金集是体系的度量基准：分层（冒烟/回归/挑战）、版本化（代码×数据×裁判三元组）、防污染（答案保密、金丝雀串）、保鲜（坏案例单向回流）。 门禁用相对基线而非绝对阈值；非确定性输出要多次采样并计方差；门禁例外必须留痕，"为过门禁而放宽门禁"要告警。 延迟看 p50/p95/p99 而非均值，重尾分布下均值会说谎；metric 必须按任务类型切片，全局均值掩盖局部塌方。 trace 按 OTel GenAI 语义约定的形状存，保证可回放、可汇入标准观测后端；每条坏案例都要能凭 trace 复原。 Goodhart 陷阱是体系的终极敌人：定期轮换 rubric、混入对抗样本、以在线真实指标为最终裁决。 结论 一个智能体团队的迭代速度上限，不由模型能力决定，而由评估体系的置信度决定——敢不敢合并、敢不敢上线、敢不敢切模型，背后都是"我们的分数可信吗"。评估与监控模式的全部工程细节（消偏、防污染、分位值、门禁纪律）都在回答同一个问题：如何让度量在噪声、偏差与博弈权衡的围攻下依然指向真相。把这个体系搭好，第 9 章的学习与适应才有安全的燃料，前十八章的每一个模式才有被验证的机会。 19.8 延伸阅读与参考链接 论文 - MT-Bench / LLM-as-judge（裁判一致性与四类偏差的系统验证）：arXiv:2306.05685 - HELM（"整体评估"方法论，多维度剖面）：arXiv:2211.09110 - SWE-bench（真实 issue 基准与"改测试作弊"讨论）：arXiv:2310.06770 - GAIA（测试集答案私有化的抗污染设计）：arXiv:2311.12983 - τ-bench（工具调用对话评测与 pass^k 指标）：arXiv:2406.12045 - RAGAS（RAG 评估的可计算维度拆解）：arXiv:2309.15217 官方文档与规范 - OpenTelemetry GenAI 语义约定（gen_ai.* 属性族）：https://opentelemetry.io/docs/specs