&quot;) out = sched.run() for line in out[&quot;log&quot;]: print(line) print(f&quot;
结果：{out['results']}&quot;) assert &quot;fix&quot; in out[&quot;results&quot;] and &quot;test&quot; in out[&quot;results&quot;], &quot;高价值链路必须完成&quot; try: Scheduler({&quot;a&quot;: Task(&quot;a&quot;, [&quot;b&quot;], est=1, deadline=9, value=1, run=lambda: &quot;&quot;), &quot;b&quot;: Task(&quot;b&quot;, [&quot;a&quot;], est=1, deadline=9, value=1, run=lambda: &quot;&quot;)}, budget=10).topo_waves() except CycleError as e: print(f&quot;
环检测验证：{e}&quot;) 20.6.2 框架集成实现（LangGraph Send API：拓扑波次并行调度） LangGraph 的 Send API 允许一个节点在运行时向下游节点派发任意数量的并行实例（官方文档），正好承接本章"拓扑分波、波内并行"的执行模型：dispatcher 按已完成集合算出当前波的就绪任务，用 Send 并行派发；worker 执行后汇入追加式状态；collect 判断是否还有波次。在 langgraph==1.2.12 实测通过（依赖顺序已用断言验证，无需模型调用）。 &quot;&quot;&quot;LangGraph Send API：拓扑波次并行调度（langgraph==1.2.12 实测）。 依赖：pip install langgraph 运行：python ch20_langgraph_waves.py &quot;&quot;&quot; from __future__ import annotations import operator from typing import Annotated, TypedDict from langgraph.graph import END, START, StateGraph from langgraph.types import Send TASKS = { # 依赖图：波1={a,b} 波2={c,d} 波3={e} &quot;a&quot;: {&quot;deps&quot;: []}, &quot;b&quot;: {&quot;deps&quot;: []}, &quot;c&quot;: {&quot;deps&quot;: [&quot;a&quot;, &quot;b&quot;]}, &quot;d&quot;: {&quot;deps&quot;: [&quot;a&quot;]}, &quot;e&quot;: {&quot;deps&quot;: [&quot;c&quot;, &quot;d&quot;]}, } class St(TypedDict): ready: list[str] # 当前波就绪任务（dispatch 覆写） results: Annotated[list[str], operator.add] # 追加式执行结果 executed: Annotated[list[str], operator.add] # 追加式已完成清单 def dispatch(state: St) -&gt; dict: &quot;&quot;&quot;Kahn 分波：从已完成集合推导当前波的就绪任务（生产中此处按优先级排序）。&quot;&quot;&quot; done = set(state[&quot;executed&quot;]) ready = [t for t in TASKS if t not in done and all(d in done for d in TASKS[t][&quot;deps&quot;])] print(f&quot;[dispatch] 本波派发：{ready}（已完成：{sorted(done)}）&quot;) return {&quot;ready&quot;: ready} def fan_out(state: St): &quot;&quot;&quot;Send API：为每个就绪任务派发一个并行 worker 实例（空列表=本波无任务）。&quot;&quot;&quot; return [Send(&quot;worker&quot;, {&quot;tid&quot;: t}) for t in state[&quot;ready&quot;]] def worker(task: dict) -&gt; dict: print(f&quot; [worker] 执行 {task['tid']}&quot;) return {&quot;results&quot;: [f&quot;{task['tid']}:ok&quot;], &quot;executed&quot;: [task[&quot;tid&quot;]]} def collect(state: St) -&gt; dict: return {} # 汇合点：仅等待所有 worker 完成 def more_waves(state: St) -&gt; str: if len(set(state[&quot;executed&quot;])) &lt; len(TASKS): return &quot;dispatch&quot; # 未完成 → 回到 dispatch 开新波 return END g = StateGraph(St) g.add_node(&quot;dispatch&quot;, dispatch) g.add_node(&quot;worker&quot;, worker) g.add_node(&quot;collect&quot;, collect) g.add_edge(START, &quot;dispatch&quot;) g.add_conditional_edges(&quot;dispatch&quot;, fan_out, [&quot;worker&quot;]) g.add_edge(&quot;worker&quot;, &quot;collect&quot;) g.add_conditional_edges(&quot;collect&quot;, more_waves, [&quot;dispatch&quot;, END]) app = g.compile() if __name__ == &quot;__main__&quot;: out = app.invoke({&quot;ready&quot;: [], &quot;results&quot;: [], &quot;executed&quot;: []}) print(f&quot;
执行结果：{out['results']}&quot;) assert set(out[&quot;executed&quot;]) == set(TASKS), &quot;全部任务应被执行&quot; idx = out[&quot;results&quot;].index assert idx(&quot;a:ok&quot;) &lt; idx(&quot;c:ok&quot;) and idx(&quot;b:ok&quot;) &lt; idx(&quot;c:ok&quot;) assert idx(&quot;c:ok&quot;) &lt; idx(&quot;e:ok&quot;) and idx(&quot;d:ok&quot;) &lt; idx(&quot;e:ok&quot;) print(&quot;依赖顺序验证通过：跨波无乱序，波内并行完成。&quot;) 20.6.3 生产化改造清单 错误处理：拓扑环、未知依赖、任务执行异常三路都必须显式报错或降级；环报错要列出环上任务，执行异常计入该任务的风险信号与重试预算。 超时：每个任务带工期上限，超时按失败处理并触发降级阶梯；调度器自身重排频率设上限，防止病态图导致的排序风暴。 并发：波内并行宽度受并发额度约束（信号量）；多 worker 场景下调度决策集中仲裁，避免各自为政。 状态持久化：队列、已完成集合、预算账户落检查点（第 12 章），崩溃后从检查点恢复且已执行任务凭幂等记录跳过。 可观测：每条调度决策记录"当时分数、被跳过的候选、原因"，支持回放审计；队列长度、等待时间分位、降级率为一等指标。 预算治理：token、时间、并发三类预算分账户记账；预算消耗速率进监控，异常增速（重试风暴）触发熔断。 信号校准：工期与价值估计定期与实测对账（第 19 章的 metric 提供实测值），系统性高估/低估自动校正。 老化与防饥饿：等待时间计入优先级；任何任务的等待时长设硬上限，超限强制执行或升级人工。 成本控制：重排只在波间进行（波内抢占代价高）；打分函数保持 O(n log n)，任务量上千时增量化。 20.7 概览 / 核心要点 / 结论 本章小结 优先级排序把"先做哪个"从直觉升级为算法：先承认四类性质迥异的稀缺资源（上下文窗口挤占型、token/资金消耗型、墙钟时间外部强加型、并发额度易逝型），再用依赖深度、截止松弛、价值、风险、成本五类信号打分；拓扑排序（Kahn，1962）保证执行序的合法性，波内优先级与波间动态重排（借鉴 EDF 的截止期思想与 UCB 的探索预算思想）保证效率与适应性，预算耗尽时按价值保全原则沿预配的降级阶梯优雅收场。这一整套机制的零件全部来自运筹学、实时系统与队列工程几十年的积累，agent 工程的新贡献只是让"工期与价值的估计"也可以外包给模型。 核心要点 四类稀缺资源管理方式不同：上下文靠控并发宽度，预算靠账户制记账熔断，时间靠松弛量而非剩余量，并发额度靠"不用即浪费"的分配观。 依赖深度进拓扑结构而非打分函数；截止期用松弛量度量且松弛为负时一票否决（降级或放弃，不让死任务拖垮队列）。 价值密度（价值/成本）是资源受限场景的核心比值；价值信号要防寻租，用完成后的实际价值回填校准。 静态排序可预测，动态重排适应变化；重排要配老化（防饥饿）、迟滞带（防震荡）、波间粒度（避免高代价抢占）。 Kahn 拓扑排序给出波次结构：波次即并行边界（第 3 章），环是错误路径必须报错定位。 优雅降级三纪律：预先配置阶梯（完整→简化→占位）、降级必打标并进监控、降级率超阈值告警；价值密度低过占位档时，诚实放弃优于化妆失败。 BabyAGI 的教训：能跑的任务队列不等于能用的任务队列——无优先级、无终止控制、无预算的自治循环是事故现场。 与第 16 章合体才是完整资源管理：本章定"先做哪个"，资源感知定"每个用多贵的模型"。 结论 排序就是预演放弃。一个系统怎么给任务排序，暴露了它认为什么重要；一个系统在预算耗尽时牺牲什么，暴露了它的真实价值观。把这套价值观从隐性的随机行为变成显性的、可审计的打分函数与降级阶梯，是智能体系统从玩具走向受托责任体的必要一步——用户把资源和时间交给一个自治系统，理应得到"它会像称职的助理一样分轻重缓急"的保证。 20.8 延伸阅读与参考链接 论文 - Kahn 拓扑排序（1962，CACM，波次定序与环检测的源头）：DOI - Liu &amp; Layland 的 EDF（1973，JACM，截止期调度的最优性保证）：DOI - UCB1（2002，"给不确定性定价"的有限时间 regret 分析）：DOI - LLMCompiler（LLM 调用的任务 DAG 并行执行）：arXiv:2312.04511